from pathlib import Path
import json,csv,re
D=Path(__file__).resolve().parent
T=[]; I=[]; P=[]; C=[]; AREAS={}
DATE='As of November 2026, '
def talk(r,date,sp,pg,title,summary,kind='talk'):
 T.append(dict(record=r,date=date,speaker=sp,pages=pg,title=title,kind=kind,summary=summary))
def item(r,pg,kind,title,notes,statement,cl,fate,status,refs=(),reconstruction='',literal='correct with missing hypotheses',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high',speaker='',area=''):
 n=1+sum(x['record']==r for x in I);i=f'1980-{r}.{n}'
 x=dict(id=i,record=r,pages=pg,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cl},fate=fate,present_status=DATE+status,literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
 if speaker:x['speaker']=speaker
 I.append(x);AREAS[i]=area
 return i
def corr(pg,place,reads,correct,evidence,typ='faithful_error',applies='both'):
 C.append(dict(page=pg,place=place,transcription_reads=reads,should_read=correct,evidence=evidence,applies_to=applies,type=typ))
def prob(id,title,statement,occ,status,refs):
 P.append(dict(id=id,title=title,statement=statement,occurrences=occ,status=DATE+status,status_date='2026-11',refs=refs))
def save():
 for name,obj in [('talks',T),('items',I),('problems',P),('areas',AREAS)]:
  (D/f'autumn_{name}.json').write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
 with (D/'autumn_corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(C)

# Record 490. The preceding page is a duplicated boundary, not a Fuchs talk.
talk(490,'1980-09-22','D. B. Fuchs','P000916-P000918','Intersection homology, duality, and the L2 comparison',r'''The dated Fuchs heading begins on P000917; the first line of P000918 finishes the discussion of Deligne’s construction. The talk explains allowable chains, Poincar\'e duality, the two-sphere nodal example, a proposed comparison with \(L^2\)-cohomology, and isolated-singularity truncation. This continues the subject indexed in 1979-484.1--4. The catalogue’s P000916 is an undated continuation of Zakharov’s Benney-equation discussion already indexed as 1979-488.1--7: hydrostatic equations, height conservation, additional conservation laws, a Hamiltonian layer formulation, a two-horizontal-dimensional extension, kinetic interpretation, and Gelfand’s collective-equation remark. It is covered here by this explicit boundary cross-reference, without creating a second occurrence or attributing it to Fuchs.''')
item(490,'P000917','definition','Stratifications and middle-perversity allowable chains',r'''The notes give \(X=X_{2n}\supset X_{2n-2}\supset X_{n-3}\supset\cdots\), locally constant stratum geometry, and \(\dim(\sigma_j\cap X_{2n-i})=j-2i\).''',r'''Let \(X\) be a pure complex \(n\)-dimensional variety with a conically locally trivial stratification by even real codimension. For middle perversity \(\bar m(c)=\lfloor(c-2)/2\rfloor\), a PL \(j\)-chain \(\xi\) is allowable if \(\dim(|\xi|\cap X_{2n-c})\le j-c+\bar m(c)\), and its boundary is allowable with \(j\) replaced by \(j-1\). Their chain complex defines \(IH_j^{\bar m}(X)\).''','E',r'''Already announced in 1977 and published before this talk: \citet[\S\S1.1,1.3]{goreskymacpherson1980intersection}. The same construction occurs in 1979-484.1.''','the construction is standard; the displayed equality and codimension indices are not a correct definition.', ['goreskymacpherson1980intersection'],reconstruction=r'''The inequality, boundary condition, dimension convention, and perversity are supplied explicitly; the inconsistent displayed formula is not silently repaired.''',literal='false as written',area='Intersection homology')
item(490,'P000917','theorem','Poincare duality for intersection homology',r'''\ru{В этих когом. есть двойств. Пуанкаре.}''',r'''For a compact oriented real \(d\)-dimensional stratified pseudomanifold and complementary perversities \(\bar p(c)+\bar q(c)=c-2\), the intersection pairing \(IH_j^{\bar p}(X;\mathbb Q)\otimes IH_{d-j}^{\bar q}(X;\mathbb Q)\to\mathbb Q\) is perfect. On complex varieties the even-codimension stratification makes middle perversity self-complementary on the relevant strata.''','E',r'''The duality theorem is \citet[\S3.3]{goreskymacpherson1980intersection}; no new 1980 conjecture is being posed.''','duality holds with these compactness, orientation, coefficient and perversity qualifications.',['goreskymacpherson1980intersection'],area='Intersection homology')
item(490,'P000917','construction','The nodal union of two spheres and failure of homotopy invariance',r'''Two \(2\)-spheres are joined at one point. Ordinary groups in degrees \(0,1,2\) are \(\mathbb Z,0,\mathbb Z^2\); the MacPherson groups are \(\mathbb Z^2,0,\mathbb Z^2\). A path through the node is forbidden.''',r'''Stratify \(X=S^2\vee S^2\) by its node and smooth complement. Middle-perversity intersection homology is the homology of the disjoint normalization \(S^2\sqcup S^2\), hence the displayed groups. Intersection homology is not invariant under arbitrary homotopy equivalence. It is invariant under homeomorphism of suitable pseudomanifolds; the two statements are compatible.''','E',r'''This is the elementary nonnormal-curve model of the allowable-chain theory; topological invariance is \citet[\S3.2]{goreskymacpherson1980intersection}. The group calculation follows directly from the chain restriction.''','the displayed groups are correct; the example demonstrates failure of ordinary duality, while general failure of homotopy invariance requires the distinction between homotopy and homeomorphism.',['goreskymacpherson1980intersection'],literal='correct',development='annotated',area='Intersection homology')
item(490,'P000917','conjecture','Intersection cohomology versus L2 cohomology',r'''\ru{Гипотеза: совпадают с \(L_2\)-когомологиями.} Borel’s interest is mentioned, but no metric, domain of the differential, compactification or arithmetic hypothesis is specified.''',r'''A precise later specialization is the Zucker comparison: for an arithmetic quotient \(X^\circ=\Gamma\backslash D\) of a Hermitian symmetric domain, its Baily--Borel compactification \(X\), and the metrized local system attached to a finite-dimensional algebraic representation, the sheaf of locally square-integrable forms with square-integrable differential represents the middle intersection complex on \(X\). This is a formulation from the literature, not an assertion that the notebook supplies those hypotheses.''','B',r'''\citet[theorem on p.~3]{looijenga1988l2} proves this arithmetic specialization; independent work of Saper--Stern was announced in February 1987 and published in 1990. The missing metric/domain data prevent an exact match of the notebook sentence to that theorem.''','the cited specialization is proved. The sentence in the notebook is underdetermined as a general mathematical conjecture and is not entered as a newly open problem.',['looijenga1988l2','saperstern1990l2'],reconstruction='The arithmetic setting and differential domain are explicitly later hypotheses.',match='partial',confidence='medium',area='Intersection homology')
item(490,'P000917-P000918','method','Isolated singularities and Deligne truncation',r'''For one isolated singularity the notes say that above half the dimension the groups agree with ordinary groups, and below it they follow by duality; the next page calls Deligne’s general definition inductive.''',r'''For a compact pure complex \(n\)-fold with isolated singularities, rational middle intersection homology satisfies \(IH_j(X)=H_j(X\setminus\Sigma)\) for \(j<n\), \(IH_n(X)=\operatorname{im}[H_n(X\setminus\Sigma)\to H_n(X)]\), and \(IH_j(X)=H_j(X)\) for \(j>n\). In sheaf language the intersection complex is obtained from the constant sheaf on the regular stratum by successive derived direct images and perversity truncations.''','E',r'''The sheaf formulation was proposed by Deligne in 1976 and is formalized in \citet[\S\S1--3]{goreskymacpherson1983intersection}; the isolated-singularity formula is the allowable-chain calculation.''','the middle-degree image is essential. The notebook alternates homology and cohomology terminology, so the displayed high-degree assertion is read homologically.',['goreskymacpherson1980intersection','goreskymacpherson1983intersection'],reconstruction='The precise isolated-singularity formula and the middle-degree clause are editorial reconstruction.',match='partial',verification='indirect',area='Intersection homology')
corr('P000916','Academic-year boundary','The catalogue includes this page in records 490--491.','Treat the Benney/Zakharov material as the continuation already indexed in 1979-488.1--7, not as a statement by Fuchs or Graev.','The first explicit date and Fuchs heading occur on P000917; the supplied previous index identifies every mathematical theme on P000916.','provenance')
corr('P000917','Filtration and formula (2)',r'\(X_{n-3},X_{n-4}\) after \(X_{2n-2}\); \(\dim(\sigma_j\cap X_{2n-i})=j-2i\).',r'Use consistently real-dimensional skeleta and \(\dim(|\xi|\cap X_{2n-c})\le j-c+\bar m(c)\), also for \(\partial\xi\).',r'Scan inspected: the anomalous indices, equality sign and \(j-2i\) really are present. This is a mathematical emendation, not a mistranscription.')
save()

# Record 491.
talk(491,'1980-09-22','M. I. Graev','P000916-P000918','Admissible families of curves and local integral geometry',r'''Graev’s actual heading is on P000918. He discusses weighted curve transforms, differential forms on curves through a point, the distinction between closure and point-supported inversion when that incidence fiber is one-dimensional, and quotienting trivial exact forms. The two explicit FA references are identified separately: Gelfand--Gindikin--Shapiro, 13(2), 1979, and Gelfand--Graev, 14(4), 1980; the second does not have the same author list. The preceding Fuchs and Zakharov material is not reassigned to Graev.''')
item(491,'P000918','construction','The weighted curve transform and incidence fiber',r'''An \((n+k-1)\)-parameter family is written \(x_i=\varphi_i(x_1,\xi)\), with positive weight \(\chi\), and \(I_\chi f(\xi)=\int f(x_1,\varphi_1,\ldots,\varphi_n)\chi\,dx_1\). The set of curves through \(x^0\) is \(\Gamma_{x^0}\), of dimension \(k\).''',r'''On a domain \(D\subset\mathbb R^n\), let a smooth incidence submanifold \(Z\subset D\times\Gamma\), \(\dim\Gamma=n+k-1\), have submersive projections and one-dimensional fibers over \(\Gamma\). Locally write \(x_i=\varphi_i(x_1,\xi)\), \(2\le i\le n\). For \(f\in C_c^\infty(D)\), set \(I_\chi f(\xi)=\int f(x_1,\varphi_2,\ldots,\varphi_n)\chi(x_1,\xi)\,dx_1\). Transversality gives \(\dim\Gamma_x=k\).''','E',r'''The general local framework is in \citet[\S1]{gelfandgindikinshapiro1979local}; the \(k=1\) setting is written explicitly in \citet[\S1, equations (1)--(4)]{gelfandgraev1980admissible}, received 16 June 1980 and published in issue 14(4).''','this is a standard double-fibration transform. The redundant coordinate and parameter indices in the notebook require correction.',['gelfandgindikinshapiro1979local','gelfandgraev1980admissible'],literal='false as written',area='Integral geometry')
item(491,'P000918','problem','Local inversion from curves through a point',r'''Find families permitting recovery using integrals over curves through the point or infinitesimally nearby; these are called admissible.''',r'''For the preceding incidence family, seek a differential operator on transform data and cycles in \(\Gamma_x\) whose periods recover \(f(x)\), or a nonzero distribution supported at \(x\). Closure of a form on \(\Gamma_x\) alone is insufficient: its relevant period must be nonzero and normalized.''','E',r'''\citet[introduction and \S1]{gelfandgindikinshapiro1979local} explicitly distinguishes closed range forms from nonvanishing inversion periods; it also explains the real/complex distinction. This is the published research program being explained, not evidence of an unsolved theorem with stated quantifiers.''','the construction is established in the cited admissible settings. No blanket inversion theorem for arbitrary curve families is asserted.',['gelfandgindikinshapiro1979local'],match='partial',area='Integral geometry')
item(491,'P000918','definition','Admissible first-order differential forms',r'''\(\mathcal H_xF=\sum a_{ij}(x_1,\xi)\partial_{\xi_j}F\,d\xi_i+F\sum b_i(x_1,\xi)d\xi_i\). Admissibility means that \(\mathcal H_xI_\chi f\) is closed for every \(f\); for \(k>1\) this is said to be the complete definition.''',r'''An operator taking data functions to differential one-forms restricted to \(\Gamma_x\) is admissible when \(d_{\Gamma_x}(\mathcal H_x I_\chi f)=0\) for all test functions \(f\). Nontriviality is a separate condition after quotienting exact operators; local recovery also needs a nonzero period.''','E',r'''This is the closed-form approach of \citet[\S1]{gelfandgindikinshapiro1979local}. The notebook’s closure criterion is meaningful in dimensions \(k>1\), but does not itself imply an inversion formula.''',r'the definition is mathematically meaningful once the omitted target \(\Gamma_x\) and the distinction from inversion are restored.',['gelfandgindikinshapiro1979local'],area='Integral geometry')
item(491,'P000918','definition','The one-dimensional incidence case and support at a point',r'''For \(k=1\), every one-form is closed; require \(f\mapsto\int\mathcal H_xI_\chi f\) to be concentrated at \(x\).''',r'''For \(\dim\Gamma_x=1\), impose instead that the period functional, with its cycle and support assumptions specified, is a distribution supported at \(x\). Such a distribution is a finite linear combination of derivatives of \(\delta_x\). To recover the value \(f(x)\), one needs the functional to be a nonzero multiple of \(\delta_x\), or additional data to invert its differential action.''','A',r'''The exactly contemporary \(n\)-dimensional-curve-complex treatment is \citet[\S1, Definitions 1--2]{gelfandgraev1980admissible}; the manuscript was received before the talk, and the journal issue is 1980(4).''','the support condition remains distinct from value recovery; the notebook does not supply a cycle or normalization.',['gelfandgraev1980admissible'],match='partial',area='Integral geometry')
item(491,'P000918','construction','Quotient by trivial exact forms',r'''\(\mathcal H_xF=d(\mu F)\) is called trivial; the quotient by such functionals is important.''',r'''For a closed one-cycle \(\gamma\subset\Gamma_x\) and a single-valued smooth \(\mu F\), \(\int_\gamma d(\mu F)=0\). Hence one quotients admissible operators by these exact operators when studying nonzero period functionals.''','E',r'''The exact-form quotient is part of the local integral-geometry construction in \citet[\S1]{gelfandgindikinshapiro1979local}; the zero-period assertion is Stokes' theorem.''','the quotient removes operators that cannot contribute a period inversion formula.',['gelfandgindikinshapiro1979local'],literal='correct',area='Integral geometry')
corr('P000918','Curve coordinates and incidence equations',r'\(\xi=(\xi_1,\ldots,\xi_n)\), then \((\xi_1,\ldots,\xi_{n+k-1})\); \(f(x_1,\varphi_1,\ldots,\varphi_n)\); \(x_i^0=\varphi_i(x_i^0,\xi)\).',r'Use \(\xi\in\mathbb R^{n+k-1}\), \(\varphi_2,\ldots,\varphi_n\), and \(x_i^0=\varphi_i(x_1^0,\xi)\), \(2\le i\le n\).','The scan confirms the incompatible indices. The corrected dimensional bookkeeping is corroborated by Gelfand--Graev, equations (2)--(4).')
corr('P000918','FA references','Both issue references are placed after Gelfand--Gindikin--Shapiro.','FA 13(2) is Gelfand--Gindikin--Shapiro (1979); FA 14(4) is Gelfand--Graev (1980).','The abbreviated author line and issue numbers are visible; both primary Math-Net records and full articles were opened.','provenance')
save()

# Refine the support condition after reading the primary article, section 2.
x=next(x for x in I if x['id']=='1980-491.4')
x['statement']=r'''For \(\dim\Gamma_x=1\), the published definition requires the period functional to vanish for test functions vanishing near \(x\). In the specific first-order incidence setting of Gelfand--Graev this implies \(L_xI_\chi f=c_x f(x)\). The authors further point out that for real curves the local inversion constant is necessarily zero; the support condition is therefore not itself a nonzero inversion formula.'''
x['fate']=r'''The exactly contemporary treatment is \citet[\S2, Definition 1 and the following remark]{gelfandgraev1980admissible}; received 16 June 1980, published in issue 14(4). Its point-evaluation conclusion is stronger than the general distribution-theoretic fact that a point-supported distribution can contain delta derivatives.'''
x['present_status']=DATE+'the precise published support condition is established; nonvanishing, the real/complex setting and the choice of cycle remain essential to an inversion assertion.'
x['publication_match']='exact'

# Record 492.
talk(492,'1980-10-13','I. M. Gelfand','P000919-P000923','Double fibrations, differential equations, and Segre structures',r'''The actual talk occupies P000919--P000921. It passes from a two-parameter family of plane curves and its dual differential equation to incidence double fibrations, homogeneous examples, separate-coordinate equivalence, and the coframe definition of Segre structures. The explicit Inventiones reference is Faran’s 1980 paper. P000922 begins the separately dated 20 October session, so its Goncharov, Fuchs and Beilinson interventions belong to record 493. The second-order-equation discussion recurs from 1976-403.1--5.''')
item(492,'P000919','construction','A second-order equation and its dual family',r'''Starting with \(y''=F(x,y,y')\), the notes write a general integral \(y=\varphi(x,\xi,\eta)\), then exchange \((x,y)\) with \((\xi,\eta)\).''',r'''A regular scalar second-order ODE determines locally a two-parameter family of solution graphs. Conversely, if \(\det\partial(\varphi,\varphi_x)/\partial(\xi,\eta)\ne0\), the parameters can be eliminated from \(y=\varphi\), \(p=\varphi_x\), producing \(y''=F(x,y,p)\). A dual scalar ODE is obtained by regarding the incident parameters as curves, provided the dual projection has the corresponding nondegeneracy and graph property.''','E',r'''This classical incidence interpretation and duality are treated in \citet[\S\S22--23]{cartan1924projective}. It is an exact subject recurrence of 1976-403.1 and 1976-403.3, not a new 1980 proposal.''','the correspondence is local; arbitrary two-parameter families can fail the determinant condition.',['cartan1924projective'],area='Differential geometry')
item(492,'P000919','problem','Straightening a family of curves by point transformations',r'''Can the family be reduced to \(\xi x+\eta y=1\) by independent changes in the point and parameter planes?''',r'''For a nondegenerate local path geometry, ask whether a local diffeomorphism of the point plane takes its unparametrized paths to projective lines; a separate parameter change merely relabels the paths. The criterion is vanishing of Cartan’s projective curvature invariants for the corresponding second-order ODE. The displayed affine line chart omits lines outside that chart.''','E',r'''Solved in the classical equivalence theory: \citet[\S\S22--24]{cartan1924projective}. The same question is 1976-403.1; the notebook supplies no new unrestricted linearization theorem.''','the local criterion is established. A general equation is not point-equivalent to the flat line family.',['cartan1924projective'],area='Differential geometry')
item(492,'P000919-P000920','definition','Incidence manifolds and double fibrations',r'''There are maps \(A\to B\), \(A\to\Gamma\), and a pair of projections is required to specify a point of \(A\) uniquely. A hypersurface \(f(z,w)=0\) is considered modulo separate transformations in \(z,w\).''',r'''A regular incidence geometry is a smooth submanifold \(Z\subset B\times\Gamma\) with submersive projections. Joint injectivity of two maps \(A\to B,\Gamma\) identifies their points set-theoretically; to identify \(A\) smoothly with a submanifold one also needs an immersion and appropriate embedding condition. Equivalence consists of local product maps \((b,\gamma)\mapsto(F(b),G(\gamma))\) preserving \(Z\).''','E',r'''The differential-equation case is classical in \citet[\S\S22--23]{cartan1924projective}; local integral geometry uses the same incidence organization in \citet[\S1]{gelfandgindikinshapiro1979local}.''','the formulation is standard with the regularity conditions made explicit.',['cartan1924projective','gelfandgindikinshapiro1979local'],reconstruction='The embedding hypotheses distinguish the smooth formulation from the set-theoretic uniqueness in the notes.',area='Integral geometry')
item(492,'P000920','construction','Homogeneous double fibrations and the intersection stabilizer',r'''Take \(A=G\), \(B=H\backslash G\), and \(\Gamma=K\backslash G\); matrix examples use unitary and triangular subgroups.''',r'''For closed subgroups \(H,K\) of a Lie group \(G\), the natural joint map from \(G\) has fibers the left cosets of \(H\cap K\). The effective incidence manifold is \((H\cap K)\backslash G\), with its two quotient maps; the map from \(G\) itself is injective only if \(H\cap K=\{1\}\). Smooth embeddedness of its image needs a further regularity hypothesis.''','E',r'''This is the standard homogeneous incidence construction underlying the local integral-geometric framework of \citet[\S1]{gelfandgindikinshapiro1979local}; the stabilizer correction follows directly from equality of the two cosets.''','the construction is valid after accounting for the common stabilizer.',['gelfandgindikinshapiro1979local'],literal='false as written',match='partial',development='annotated',area='Lie groups and homogeneous geometry')
item(492,'P000920','remark','The hyperbolic and horospherical matrix example',r'''For \(GL(n,\mathbb C)\), unitary and triangular subgroups are proposed; the \(n=2\) case is described as a Lobachevsky plane with horospheres. The choice of subgroup is tentative.''',r'''A precise nearby standard example is hyperbolic three-space \(SL(2,\mathbb C)/SU(2)\), with oriented horospheres parametrized by \(SL(2,\mathbb C)/(MN)\), where \(M\) is the compact diagonal subgroup and \(N\) upper unipotent. A full complex Borel subgroup instead parametrizes the sphere at infinity. \(GL(2,\mathbb C)/U(2)\) has real dimension four, so it is not a hyperbolic plane.''','E',r'''The group/quotient calculation identifies the classical intended example; it does not identify the notebook’s tentative triangular subgroup with the horosphere stabilizer. Its integral-geometric context is \citet[\S1]{gelfandgindikinshapiro1979local}.''','the exact example requires the subgroup and dimension corrections stated here.',['gelfandgindikinshapiro1979local'],reconstruction='The SL(2,C), SU(2), MN formulation is editorial reconstruction of the example, not a transcription.',literal='false as written',match='thematic only',verification='indirect',confidence='medium',area='Integral geometry')
item(492,'P000920-P000921','construction','Segre families and separate-coordinate equivalence',r'''The notes cite an Inventiones paper on Segre families, use \(\tau(z,\zeta)=0\), and allow independent holomorphic changes in its two sets of variables and multiplication of \(\tau\) by a nonvanishing factor.''',r'''A real-analytic hypersurface in \(\mathbb C^{n+1}\) has a complexified defining equation \(\tau(z,\zeta)=0\). Its fibers over \(\zeta\) form the Segre family. Near a regular nondegenerate point, consider the equivalence of this complex incidence hypersurface under independent biholomorphisms in \(z\) and \(\zeta\). Multiplication by a nonzero function preserves the hypersurface and rescales the contact form \(d_z\tau\) on it.''','E',r'''The exact bibliographic identification is \citet[pp.~135--172]{faran1980segre}. The paper was received 15 November 1979, revised 28 April 1980 and published in June 1980; its Berkeley thesis antecedent is 1978. Publisher metadata, rather than the full proof, was checked.''',"Faran’s article is an exact subject match; no assertion that its detailed normal-form theorem has been independently verified is made.",['faran1980segre'],match='exact',verification='publisher metadata checked',area='Several complex variables')
item(492,'P000920-P000921','definition','Adapted coframes and the Segre structure group',r'''An adapted coframe \((\theta,\theta^\alpha,\theta_\alpha)\) changes by a block matrix with diagonal blocks \(u,U,V\) and independent \(\theta\)-terms in both families. Several displayed indices and stars are inconsistent.''',r'''On a complex manifold of dimension \(2n+1\), an adapted coframe changes as \(\widehat\theta=a\theta\), \(\widehat\theta^\alpha=A^\alpha_\beta\theta^\beta+b^\alpha\theta\), and \(\widehat\theta_\alpha=B_\alpha^\beta\theta_\beta+c_\alpha\theta\), where \(a\ne0\) and \(A,B\) are invertible. This preserves the common hyperplane and its two distinguished rank-\(n\) subbundles. If a normalized Levi pairing is imposed, \(A,B,a\) satisfy its additional compatibility relation; the unnormalized block display alone does not impose it.''','E',r'''The notebook explicitly associates this structure with \citet[pp.~135--172]{faran1980segre}. The corrected coframe action is elementary matrix bookkeeping; the exact normalization used in the article was not read.''','the unnormalized reduction is well-defined. The defective displayed transformation laws are not literal identities.',['faran1980segre'],literal='false as written',match='partial',verification='publisher metadata checked',confidence='medium',area='Differential geometry')
item(492,'P000921','claim','Frobenius conditions for the two Segre foliations',r'''Both ideals generated by \((\theta,\theta^1,\ldots,\theta^n)\) and by \((\theta,\theta_1,\ldots,\theta_n)\) must be closed under exterior differentiation; invariants of curve and surface families are requested.''',r'''For an adapted coframe, require \(d\theta,d\theta^\alpha\equiv0\pmod{\theta,\theta^1,\ldots,\theta^n}\), and the analogous condition for the lower-index forms. Frobenius' theorem then gives two local rank-\(n\) foliations. Their transversality and, for a nondegenerate Segre geometry, nondegeneracy of the Levi pairing must also be required. The request for invariants is an equivalence problem, not an assertion that every such structure is flat.''','E',r'''The integrability implication is the classical Frobenius theorem; the intended equivalence problem is the published subject of \citet[pp.~135--172]{faran1980segre}, with the ODE antecedent in \citet[\S\S22--24]{cartan1924projective}.''','the local foliation criterion is established; no separate precise unresolved invariant problem is specified.',['faran1980segre','cartan1924projective'],match='partial',verification='indirect',area='Differential geometry')
corr('P000920','Homogeneous incidence example',r'\(A=G\), with joint injectivity of \(G\to H\backslash G\times K\backslash G\).',r'Replace \(A\) by \((H\cap K)\backslash G\), or impose \(H\cap K=\{1\}\).','The two coset projections identify precisely the left cosets of the intersection; the notebook has not imposed trivial intersection.')
corr('P000920','Lower-index coframe transformation (18)',r'The lower-index transformation has incompatible repeated indices and no visible final \(\theta\) factor.',r'Use \(\widehat\theta_\alpha=B_\alpha^\beta\theta_\beta+c_\alpha\theta\).','Scan P000920 inspected; the malformed expression is faithfully reproduced. This is the type-correct form of the block action.')
corr('P000921','Coframe transformations (21)',r'\(\theta^*=u\theta^*\) and a \(u^\alpha\theta^\alpha\) term.',r'Use one common rescaled form and a multiple of \(\theta\) in each off-diagonal term, with invertible diagonal blocks.','Scan inspected; the self-starred expression and repeated upper-index term are present. The adjacent matrix resolves the intended block transformation.')
save()

# Record 493: interventions belong to the dated 20 October session.
talk(493,'1980-10-20','A. B. Goncharov; interventions by D. B. Fuchs and A. A. Beilinson','P000921-P000926','G-structures, intersection complexes, and regular holonomic systems',r'''The session begins on P000922 with Goncharov’s definition of a G-structure and a problem about geometries on the sphere. Fuchs then revisits allowable chains, and Beilinson explains intersection complexes through differential operators, minimal extension and the regular Riemann--Hilbert correspondence, continuing through P000924. These interventions are expressly headed in the manuscript although absent from the short catalogue label. P000925 begins 27 October and belongs to records 494--495.''')
item(493,'P000922','definition','A G-structure as a reduction of the frame bundle',r'''For a smooth \(n\)-manifold \(M\), its tangent frame bundle is a principal \(GL(n,\mathbb R)\)-bundle; a \(G\)-subbundle is called a \(G\)-structure.''',r'''For a closed Lie subgroup \(G\subset GL(n,\mathbb R)\), a smooth \(G\)-structure is a principal \(G\)-subbundle of the frame bundle \(F(M)\), equivalently a reduction of its structure group. Integrability or flatness is an additional condition.''','E',r'''This is classical structure-group language underlying Cartan’s equivalence method; compare \citet[\S\S22--24]{cartan1924projective} for the projective-equation example discussed the previous week.''','the definition is standard and supplies no new classification theorem.',['cartan1924projective'],literal='correct',match='thematic only',area='Differential geometry')
item(493,'P000922','problem','Geometries on the two-sphere associated with subgroups',r'''The problem is to consider all geometries on \(S^2\) associated with different subgroups \(G\subset GL(n,\mathbb R)\).''',r'''For \(S^2\), a reduction question must use \(G\subset GL(2,\mathbb R)\). One can ask which such reductions exist, classify the reductions up to bundle isomorphism or diffeomorphism, or classify locally homogeneous integrable structures; these are different problems. The notes do not choose one, restrict the subgroups, or state an equivalence relation.''','F','No determinate classification problem can be extracted from the single sentence; the neighboring definition identifies the subject but not its quantifiers.','this remains an underspecified program in the source, not evidence of an open or undeveloped theorem.',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',area='Differential geometry')
item(493,'P000922','definition','Allowability revisited with complex-dimensional skeleta',r'''Fuchs writes \(\dim(\sigma^q\cap X_{n-i})\le q-i\), explicitly noting real codimension \(2i\). He contrasts this with bounds \(q\) and \(q-2i\).''',r'''For middle perversity and a stratum of real codimension \(2i\), the bound is \(q-2i+\bar m(2i)=q-i-1\), with the analogous boundary condition. The unrestricted \(q\) condition gives ordinary chains; the transverse \(q-2i\) condition is zero perversity. Its relation to ordinary cohomology uses duality and the normality and compact-support conventions, rather than a literal equality of arbitrary chain complexes.''','E',r'''Compare \citet[\S\S1.1,1.3,3.3]{goreskymacpherson1980intersection} and the earlier occurrences 1979-484.1 and 1980-490.1. The repeated formula is another faithfully recorded missing-index error.''','the theory is established, but the displayed middle bound differs by one from middle perversity.',['goreskymacpherson1980intersection'],literal='false as written',speaker='D. B. Fuchs',area='Intersection homology')
item(493,'P000922','method','Sheaf-local intersection cohomology and its arithmetic motivation',r'''Deligne wants a definition valid over finite fields; a local complex of sheaves should compute MacPherson’s groups. The comparison with \(L^2\) forms on the smooth locus is again mentioned.''',r'''The intersection complex is specified locally by extension and truncation from the regular stratum. This sheaf formulation admits an \(\ell\)-adic analogue over a field of characteristic different from \(\ell\). A proposed \(L^2\) identification is a separate analytic problem and requires a metric and a differential domain.''','E',r'''Deligne’s sheaf construction predates the seminar and is treated in \citet[\S\S1--3]{goreskymacpherson1983intersection}. The precise arithmetic analytic specialization is \citet[p.~3]{looijenga1988l2}. This repeats 1980-490.4--5 rather than supplying a new complete conjecture.''','the sheaf formulation is established. The notebook’s unrestricted analytic comparison remains underdetermined.',['goreskymacpherson1983intersection','looijenga1988l2'],match='partial',verification='indirect',speaker='D. B. Fuchs and A. A. Beilinson',area='Intersection homology')
item(493,'P000923','construction','Embedding a singular variety and the delta-module picture',r'''Embed \(X\) in smooth \(Y\), regard functions on \(X_{\rm reg}\) as differential equations, and extend them transversely by delta functions. A cross in the plane illustrates the construction.''',r'''If \(i:U\hookrightarrow V\) is a smooth closed embedding, the direct image \(i_+\mathcal O_U\) is a holonomic \(\mathcal D_V\)-module supported on \(U\); locally it includes all normal derivatives of a delta generator. For \(U=X_{\rm reg}\), this is first formed on \(V=Y\setminus X_{\rm sing}\), then extended across the omitted locus.''','E',r'''This is the direct-image and support formalism of holonomic systems used in \citet[\S5 and the references there]{kashiwara1984riemann}; its regular-system formulation was already circulated before the talk, as \citet[pp.~XIX.1--2]{kashiwara1980constructible} records on 22 April 1980.''','the construction is established; a single informal delta function must be read as its generated D-module.',['kashiwara1980constructible','kashiwara1984riemann'],speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000923','theorem','Minimal extension and the irreducibility hypothesis',r'''After maximal direct image the notes assert that there is a unique irreducible submodule; this is the desired extension across the singularities.''',r'''For a connected smooth dense stratum \(U\) of an irreducible variety \(X\), an irreducible regular connection has a unique intermediate extension with no nonzero submodule or quotient supported on \(X\setminus U\). For the trivial rank-one connection this is the intersection-cohomology D-module. If \(X\) is reducible, the direct sum of the componentwise extensions need not be irreducible; the cross drawn in the notes has two components.''','E',r'''The correspondence between simple regular holonomic modules and intersection complexes belongs to the regular Riemann--Hilbert theory announced in \citet[p.~XIX.1]{kashiwara1980constructible} and proved in detail in \citet[\S\S5--7]{kashiwara1984riemann}.''','the intermediate extension is canonical. The notebook’s unqualified irreducibility is false for its reducible example.',['kashiwara1980constructible','kashiwara1984riemann'],literal='false as written',speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000923-P000924','method','Derived solutions from a locally free resolution',r'''Resolve the D-module by free modules \(F_i\) and apply \(\operatorname{Hom}_{\mathcal D_Y}(F_i,\mathcal O_Y)\); the resulting cohomology is called MacPherson cohomology after a codimension shift.''',r'''The resulting sheaf complex computes \(\operatorname{Sol}(\mathcal M)=R\mathcal Hom_{\mathcal D_Y}(\mathcal M,\mathcal O_Y)\), using local resolutions. For the intersection-cohomology D-module supported on a pure \(n\)-dimensional \(X\subset Y\), with \(\dim Y=m\), one has \(\operatorname{Sol}(\mathcal M)[m]\simeq IC_X\), where \(IC_X|_{X_{\rm reg}}=\mathbb C[n]\), for the self-dual trivial local system. Thus unshifted solutions restrict in degree \(m-n\); hypercohomology, not stalk cohomology alone, gives the global groups.''','E',r'''The solution functor and derived equivalence are stated in \citet[p.~XIX.1]{kashiwara1980constructible} and \citet[Introduction and \S6]{kashiwara1984riemann}. The explicit shifts reconcile the source’s codimension remark.''','the construction is standard with the local/global and shift conventions stated.',['kashiwara1980constructible','kashiwara1984riemann'],speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000924','theorem','Flat connections and local systems',r'''The simplest systems are locally equivalent to \(\partial u/\partial x_i=0\); their solution sheaves are locally constant, while global solutions may not exist.''',r'''On a complex manifold a finite-rank holomorphic vector bundle with integrable connection is locally a constant connection and has a finite-rank local system of horizontal sections. Conversely, tensoring such a local system with \(\mathcal O\) gives the connection. Nontrivial monodromy can make the space of global horizontal sections zero.''','E',r'''This is the nonsingular starting case of \citet[Introduction]{kashiwara1984riemann}; the regular-singular extension was already announced in \citet[p.~XIX.1]{kashiwara1980constructible}.''','the local and global statements are compatible.',['kashiwara1980constructible','kashiwara1984riemann'],literal='correct',speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000924','theorem','The regular Riemann--Hilbert correspondence',r'''The notes assert equivalence between regular singular holonomic systems and MacPherson complexes, and attribute the regularity definition to Kashiwara.''',r'''On a complex manifold, the solution functor gives an anti-equivalence between the bounded derived category of regular holonomic analytic D-modules and the bounded derived category of complex-constructible sheaves. Under the standard dimension shift, the abelian category corresponds to perverse sheaves. Intersection complexes are the simple objects obtained from irreducible local systems, not all constructible complexes.''','E',r'''An explicit theorem and an inverse-functor construction were announced on 22 April 1980 in \citet[pp.~XIX.1--2]{kashiwara1980constructible}, which also acknowledges Mebkhout’s independent proof. The full paper was received 4 March 1983 and published in 1984: \citet[Main Theorem, \S6]{kashiwara1984riemann}.''','the theorem is established; identifying every regular system with a single intersection complex would be too restrictive.',['kashiwara1980constructible','kashiwara1984riemann'],reconstruction='The distinction between derived constructible complexes, perverse sheaves and simple intersection complexes is supplied.',speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000924','claim','Torsion-freeness does not characterize connections',r'''The source defines no torsion by \(f x\ne0\) for every nonzero \(f\in\mathcal D\) and nonzero \(x\in\mathcal M\), then says the system reduces to the locally constant case.''',r'''A coherent D-module which is coherent as an \(\mathcal O\)-module on a smooth complex manifold is a finite-rank vector bundle with integrable connection. D-torsion-freeness is not this hypothesis: \(\mathcal O\) itself satisfies \(\partial\cdot1=0\), whereas the rank-one free module \(\mathcal D\) is D-torsion-free and is not a finite-rank connection when the manifold has positive dimension.''','E',r'''The proper finite-rank condition is part of the holonomic-system framework of \citet[\S5]{kashiwara1984riemann}. The two counterexamples directly refute the literal criterion; the manuscript visibly writes \(f\in\mathcal D\), not \(f\in\mathcal O\).''','the source criterion is false; changing only D-torsion to O-torsion would still not supply O-coherence.',['kashiwara1984riemann'],literal='false as written',development='annotated',speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000924','claim','Regular singularities, curve tests, and finite composition series',r'''A Fuchsian equation is \(dx/dt=t^{-1}A(t)x\). The notes propose testing regularity on a sufficiently regular curve, then claim a finite irreducible filtration for any module, each factor generically a connection.''',r'''A meromorphic connection on a curve is regular singular when it admits a logarithmic lattice, so a suitable frame gives \(t^{-1}A(t)\) with \(A\) holomorphic. Higher-dimensional regularity can be tested on all appropriate analytic curve germs after pullback, not on one unspecified generic curve. Coherent holonomic D-modules have finite length locally; on an algebraic variety of finite type they have a finite composition series, and each simple factor is generically an irreducible connection on its irreducible support. Arbitrary D-modules need not have finite length.''','E',r'''These qualifications are those of regular holonomic theory; see \citet[\S5]{kashiwara1984riemann} and the regularity preprint cited in \citet[bibliography, item 2]{kashiwara1980constructible}. The ordinary equation alone is not a definition for arbitrary modules.''','the regular holonomic statements are established. The omitted coherence, holonomicity and curve quantifier are consequential.',['kashiwara1980constructible','kashiwara1984riemann'],literal='false as written',match='partial',speaker='A. A. Beilinson',area='D-modules and singularities')
corr('P000922','Allowability formula (3)',r'\(\dim(\sigma^q\cap X_{n-i})\le q-i\), with \(\operatorname{codim}_{\mathbb R}X_{n-i}=2i\).',r'For middle perversity use \(q-i-1\), and impose the corresponding boundary restriction.','Scan inspected: the right side is q-i and the real-codimension 2i parenthesis is explicit. This is not an OCR correction.')
corr('P000923','Unique irreducible submodule, assertion (6)','A unique irreducible submodule for the extension of the regular locus, with a cross as example.','Require irreducible support and an irreducible local system; for a cross use componentwise intermediate extensions.','The scan explicitly draws the cross and asserts uniqueness/irreducibility. Its regular locus has two components.')
corr('P000924','Torsion condition (13)',r'\(f\in\mathcal D\), \(f\ne0\), \(x\ne0\Rightarrow fx\ne0\), hence a locally constant system.',r'Replace the criterion by coherence over \(\mathcal O\) for a coherent D-module; D-torsion-freeness is false as a characterization.','The original scan clearly has f in D. O has the nonzero annihilator partial acting on 1, and D itself supplies the opposite counterexample.')
corr('P000924','General case, finite-length statement','Every module has a finite filtration with irreducible factors.','Use coherent holonomic modules, locally in the analytic setting or globally in the algebraic finite-type setting.','The scan says every module and finite length. Infinite direct sums already refute the unrestricted statement.')
