x.update(kind='definition',title='Regular singular equations and logarithmic lattices',notes=r'''A Fuchsian equation is written \(dx/dt=t^{-1}A(t)x\).''',statement=r'''A meromorphic connection on a complex curve is regular singular at t=0 when it admits a logarithmic lattice. In a suitable meromorphic frame its system has coefficient \(t^{-1}A(t)\) with A holomorphic near zero. A particular displayed system requires A to have this regularity; an arbitrary meromorphic A does not suffice.''',literal_correctness='correct with missing hypotheses',fate=r'''This is classical regular-singular ordinary differential equation theory, part of the regularity framework recalled in \citet[\S5]{kashiwara1984riemann}.''',present_status=DATE+'the logarithmic-lattice criterion is established; the holomorphic coefficient qualification is required.')
item(493,'P000924','claim','Testing higher-dimensional regularity on curves',r'''The notes say that it is sufficient to restrict to a sufficiently regular curve.''',r'''Regularity of a meromorphic connection can be tested by requiring regular singular pullbacks on all appropriate smooth analytic curve germs through the boundary. This is a quantified curve criterion; checking one unspecified generic curve is not such a criterion. For general holonomic modules, derived inverse image and the support stratification replace a naive restriction of equations.''','E',r'''The curve-wise formulation is part of the regular holonomic theory summarized in \citet[\S5]{kashiwara1984riemann}; the regularity preprint was already cited by \citet[bibliography, item~2]{kashiwara1980constructible}. The notebook’s quantifier is incomplete.''','the qualified regularity criterion is established. No unrestricted single-curve test is certified.',['kashiwara1984riemann','kashiwara1980constructible'],literal='correct with missing hypotheses',match='partial',speaker='A. A. Beilinson',area='D-modules and singularities')
item(493,'P000924','theorem','Finite length and generically flat simple factors',r'''In the general case every module is said to have a finite filtration with irreducible factors, each a locally constant system away from some subvariety.''',r'''Coherent holonomic D-modules have finite length locally in the analytic setting and globally on smooth algebraic varieties of finite type. Each simple factor has irreducible support and is, on a dense smooth open subset of that support, an irreducible connection, interpreted by direct image from the support. Arbitrary D-modules need not have finite length. Restricting to regular holonomic factors gives regular connections and their intermediate extensions.''','E',r'''These are the holonomic-category qualifications underlying \citet[\S5]{kashiwara1984riemann} and the regular derived equivalence announced in \citet[p.~XIX.1]{kashiwara1980constructible}. Infinite direct sums refute the literal assertion for every module.''','the finite-length theorem is established with coherence and holonomicity; its unrestricted formulation is false.',['kashiwara1984riemann','kashiwara1980constructible'],literal='false as written',match='partial',speaker='A. A. Beilinson',area='D-modules and singularities')

